sealed interface CuacaState {
    data object Memuat : CuacaState
    data class Ok(val kota: List<String>) : CuacaState
    data class Gagal(val pesan: String) : CuacaState
}

interface CuacaRepository {
    suspend fun daftar(): List<String>   // diisi dari API di modul berikutnya
}

class CuacaViewModel(private val repo: CuacaRepository) : ViewModel() {
    private val _state = MutableStateFlow<CuacaState>(CuacaState.Memuat)
    val state: StateFlow<CuacaState> = _state.asStateFlow()

    init { muat() }

    fun muat() = viewModelScope.launch {
        _state.value = CuacaState.Memuat
        _state.value = try {
            CuacaState.Ok(repo.daftar())
        } catch (e: Exception) {
            CuacaState.Gagal(e.message ?: "Terjadi kesalahan")
        }
    }
}

@Composable
fun CuacaScreen(repo: CuacaRepository) {
    val vm: CuacaViewModel = viewModel { CuacaViewModel(repo) }
    val s by vm.state.collectAsStateWithLifecycle()
    when (val st = s) {
        CuacaState.Memuat -> CircularProgressIndicator()
        is CuacaState.Gagal -> Button(onClick = { vm.muat() }) { Text("Coba lagi: ${st.pesan}") }
        is CuacaState.Ok -> LazyColumn { items(st.kota) { Text(it) } }
    }
}

