private val Context.dataStore by preferencesDataStore("pengaturan")

private val BAHASA = stringPreferencesKey("bahasa")
private val UKURAN_HURUF = intPreferencesKey("ukuran_huruf")
private val NOTIF_PROMO = booleanPreferencesKey("notif_promo")

data class Pengaturan(val bahasa: String, val ukuranHuruf: Int, val notifPromo: Boolean)

class PengaturanRepo(private val ctx: Context) {
    val pengaturan: Flow<Pengaturan> = ctx.dataStore.data.map { p ->
        Pengaturan(
            bahasa = p[BAHASA] ?: "id",
            ukuranHuruf = p[UKURAN_HURUF] ?: 16,
            notifPromo = p[NOTIF_PROMO] ?: true,
