class OnboardingRepo(private val ctx: Context) {
    suspend fun sudahDilihat(): Boolean =
        ctx.dataStore.data.map { it[SUDAH_ONBOARDING] ?: false }.first()

    suspend fun tandaiSelesai() {
        ctx.dataStore.edit { it[SUDAH_ONBOARDING] = true }
    }

    suspend fun reset() {
        ctx.dataStore.edit { it.remove(SUDAH_ONBOARDING) }
    }
}

