fun PemutarVideo(pemutar: Pemutar) {
    val lifecycleOwner = LocalLifecycleOwner.current
    DisposableEffect(lifecycleOwner) {
        val pengamat = LifecycleEventObserver { _, event ->
            when (event) {
                Lifecycle.Event.ON_PAUSE -> pemutar.jeda()
                Lifecycle.Event.ON_RESUME -> pemutar.lanjut()
                else -> Unit
            }
        }
        lifecycleOwner.lifecycle.addObserver(pengamat)
